// Hooks returns the client hooks.
func (c *GoatClient) Hooks() []Hook {
	return c.hooks.Goat
}

// Interceptors returns the client interceptors.
func (c *GoatClient) Interceptors() []Interceptor {
	return c.inters.Goat
}

func (c *GoatClient) mutate(ctx context.Context, m *GoatMutation) (Value, error) {
	switch m.Op() {
	case OpCreate:
		return (&GoatCreate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdate:
		return (&GoatUpdate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdateOne:
		return (&GoatUpdateOne{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpDelete, OpDeleteOne:
		return (&GoatDelete{config: c.config, hooks: c.Hooks(), mutation: m}).Exec(ctx)
	default:
		return nil, fmt.Errorf("ent: unknown Goat mutation op: %q", m.Op())
	}
}

